using JTradeERP.Application.Common.Exceptions;using JTradeERP.Application.Common.Inventory;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Common.Security;using MediatR;
namespace JTradeERP.Application.Features.Inventory.Adjustments.UpdateStockAdjustment;
public sealed class UpdateStockAdjustmentHandler(IApplicationDbContext db,ICurrentUserService actor):IRequestHandler<UpdateStockAdjustmentCommand,UpdateStockAdjustmentResponse>
{
 public async Task<UpdateStockAdjustmentResponse> Handle(UpdateStockAdjustmentCommand r,CancellationToken ct){var x=db.StockAdjustments.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Stock adjustment was not found.");if(x.Status!=JTradeERP.Domain.Inventory.InventoryDocumentStatus.Draft)throw new ConflictException("Only draft adjustments can be edited.");if(!db.Products.Any(p=>p.Id==r.ProductId))throw new NotFoundException("Product was not found.");if(!db.Warehouses.Any(w=>w.Id==r.WarehouseId))throw new NotFoundException("Warehouse was not found.");var old=$"{x.ProductId}|{x.WarehouseId}|{x.QuantityDelta}|{x.ReasonCode}";x.Update(r.ProductId,r.WarehouseId,r.QuantityDelta,r.ReasonCode);SecurityAuditWriter.Add(db,actor.UserId,"StockAdjustmentUpdated","StockAdjustment",x.Id.ToString(),old,$"{r.ProductId}|{r.WarehouseId}|{r.QuantityDelta}|{r.ReasonCode}");await db.SaveChangesAsync(ct);return new(StockAdjustmentMapper.ToResponse(x));}
}
